  "Create offer": ["Wystaw ofertę", "Criar oferta"],
  "{qty}× {item} at {price} gold each = {total} gold. Listing fee: {fee} gold. Traders would pay {value} each.": ["{qty}× {item} po {price} złota = {total} złota. Opłata za wystawienie: {fee} złota. Kupcy zapłaciliby po {value}.", "{qty}× {item} a {price} de ouro cada = {total} de ouro. Taxa de anúncio: {fee} de ouro. Os mercadores pagariam {value} cada."],
  "Price each": ["Cena za sztukę", "Preço unitário"],
